options.css:
:host,*{box-sizing:border-box}body,.r{margin:0;padding:0;font-family:Inter,Arial,sans-serif;color:#ecf4ff}
.r{width:100%;height:100%;padding:14px;background:
radial-gradient(circle at top right, rgba(12,84,188,.22), transparent 28%),
radial-gradient(circle at bottom left, rgba(2,132,199,.14), transparent 22%),
linear-gradient(180deg, rgba(8,15,28,.99), rgba(6,12,20,.99))}
.s{width:100%;height:100%;border:1px solid rgba(120,170,255,.14);border-radius:22px;background:rgba(10,18,32,.72);padding:16px;box-shadow:0 12px 40px rgba(0,0,0,.20), inset 0 1px 0 rgba(255,255,255,.03)}
.t{font-size:12px;text-transform:uppercase;letter-spacing:.08em;font-weight:700;color:#8bb8ff;margin-bottom:10px}
.hero{display:grid;grid-template-columns:1.35fr .9fr;gap:16px;height:100%}
.k{display:inline-flex;align-items:center;gap:8px;width:fit-content;border:1px solid rgba(96,165,250,.30);border-radius:999px;padding:6px 10px;color:#dbeafe;background:rgba(29,78,216,.14);font-size:12px;font-weight:700;margin-bottom:10px}
.brand{display:flex;align-items:center;gap:10px;margin-bottom:12px}.brand-badge{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,#2563eb,#38bdf8);display:flex;align-items:center;justify-content:center;font-weight:900;color:white}.brand-name{font-size:18px;font-weight:800;color:#f8fbff}.brand-sub{font-size:12px;color:#9ab3cf}
.h1{font-size:30px;line-height:1.06;font-weight:850;margin:0 0 10px 0}.c{font-size:13px;line-height:1.6;color:#d3deea;max-width:760px}
.tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.tag{padding:6px 10px;border-radius:999px;font-size:11px;color:#dbeafe;background:rgba(37,99,235,.12);border:1px solid rgba(96,165,250,.18)}
.hr{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.m{border-radius:16px;padding:14px;background:rgba(2,8,23,.42);border:1px solid rgba(148,163,184,.12)}.ml{font-size:11px;color:#98aeca;margin-bottom:8px;text-transform:uppercase;letter-spacing:.06em}.mv{font-size:24px;font-weight:800;line-height:1.05}.mn{margin-top:8px;color:#8ea8c7;font-size:11px}
.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{border:1px solid rgba(148,163,184,.12);border-radius:16px;padding:14px;background:rgba(2,8,23,.34)}.card .l{font-size:12px;color:#8ea8c7;margin-bottom:6px}.card .v{font-size:22px;font-weight:800;line-height:1.1}.mini{margin-top:10px;height:34px}
.w{width:100%;height:calc(100% - 22px);border-radius:16px;background:rgba(2,8,23,.28);border:1px solid rgba(148,163,184,.10);padding:12px}
.legend{display:flex;flex-wrap:wrap;gap:8px 12px;margin-top:8px}.li{display:flex;align-items:center;gap:6px;font-size:12px;color:#d2ddeb}.sw{width:10px;height:10px;border-radius:999px}
.rows{display:flex;flex-direction:column;gap:10px}.row{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center}.name{font-size:13px;color:#f2f7ff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.metric{font-size:12px;font-weight:700}.bw{position:relative;height:10px;border-radius:999px;background:rgba(148,163,184,.12);overflow:hidden;margin-top:6px}.bar{position:absolute;inset:0 auto 0 0;border-radius:999px;background:linear-gradient(90deg,#38bdf8,#2563eb)}
.nb{border-radius:16px;border:1px solid rgba(148,163,184,.10);background:rgba(2,8,23,.28);padding:14px}.nt{font-size:12px;color:#8bb8ff;text-transform:uppercase;letter-spacing:.06em;margin-bottom:10px}.ni{font-size:13px;line-height:1.5;color:#e8f2ff;margin-bottom:10px}.sub{color:#90a9c7;font-size:12px}svg{width:100%;height:100%;display:block}
.cta{margin-top:16px;display:flex;gap:10px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;border-radius:12px;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.04em}.btn-primary{background:linear-gradient(135deg,#2563eb,#38bdf8);color:white}.btn-secondary{background:rgba(37,99,235,.10);color:#dbeafe;border:1px solid rgba(96,165,250,.20)}
@media (max-width:980px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.hero{grid-template-columns:1fr}}

options.onRender:
const C=['#60a5fa','#22c55e','#f59e0b','#a78bfa','#ef4444','#14b8a6','#f472b6','#eab308'];
const arr=v=>{if(v==null)return[];if(Array.isArray(v))return v;if(Array.isArray(v.buffer))return v.buffer;if(typeof v.toArray==='function')return v.toArray();if(typeof v.get==='function'&&typeof v.length==='number'){const a=[];for(let i=0;i<v.length;i++)a.push(v.get(i));return a}return[]};
const sum=a=>a.reduce((x,y)=>x+(Number(y)||0),0);
const fb=n=>{n=Number(n)||0;if(!n)return'0 B';const u=['B','KB','MB','GB','TB'];const i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),u.length-1);const v=n/Math.pow(1024,i);return `${v>=100?v.toFixed(0):v>=10?v.toFixed(1):v.toFixed(2)} ${u[i]}`};
const fn=n=>new Intl.NumberFormat('pt-BR').format(Math.round(Number(n)||0));
const eh=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
const vf=s=>!s||!s.fields?null:(s.fields.find(f=>f.type&&f.type!=='time'&&f.type!=='string')||s.fields[1]||null);
const lf=s=>!s||!s.fields?null:(s.fields.find(f=>f.type==='string')||s.fields[0]||null);
const total=s=>{const f=vf(s);return f?sum(Array.isArray(f.values)?f.values:arr(f.values)):0};
const pts=s=>{const f=vf(s);return f?arr(f.values).map(v=>Number(v)||0):[]};
const termRows=()=>{const s=htmlGraphics.data?.series?.[0];if(!s)return[];const l=lf(s),v=vf(s);const ls=l?arr(l.values):[],vs=v?arr(v.values):[];return ls.map((x,i)=>({label:x,value:Number(vs[i])||0})).sort((a,b)=>b.value-a.value)};
const spark=(values,w=180,h=34,c='#60a5fa')=>{if(!values.length)return `<svg viewBox="0 0 ${w} ${h}"><text x="8" y="${h/2}" fill="#93a4bf" font-size="11">Sem dados</text></svg>`;const mx=Math.max(...values,1),mn=Math.min(...values,0),sp=Math.max(mx-mn,1);const p=values.map((v,i)=>{const x=(i/Math.max(values.length-1,1))*w;const y=h-((v-mn)/sp)*(h-6)-3;return `${x.toFixed(2)},${y.toFixed(2)}`}).join(' ');return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline fill="none" stroke="${c}" stroke-width="2" points="${p}" /></svg>`};

const host=htmlGraphics.htmlNode.querySelector('#heroMetrics'); if(!host) return; const srs=htmlGraphics.data?.series||[];
host.innerHTML=srs.map((s,i)=>{const t=total(s),p=pts(s),low=(s.name||'').toLowerCase(),isCount=low.includes('pacote')||low.includes('fluxo');return `<div class="m"><div class="ml">${eh(s.name||'Métrica')}</div><div class="mv">${isCount?fn(t):fb(t)}</div><div class="mn">${spark(p,160,30,C[i%C.length])}</div></div>`}).join('');

